collection.DEFAULT_THEME = "default_light";
collection.BASE_FONT_SIZE = 14;

collection.setting = function(name, fallback) {
    try {
        var p = collection.properties ? collection.properties[name] : null;
        var v = p ? p.value : null;
        if (v && typeof v === "object" && "value" in v) v = v.value;
        return (v === null || v === undefined || v === "") ? fallback : v;
    } catch (e) {
