    }
};

// The collection has one theme: antd's default light algorithm.
collection.theme = function() {
    return (collection.THEME_MAP || {})[collection.DEFAULT_THEME] || {};
};

collection.themeColors = function() {
    return collection.theme().colors || {};
};

collection.themeMetrics = function() {
