collection.weightString = function (weight) {
    if (!weight) return "normal";
    var w = parseInt(weight, 10);
    if (isNaN(w) || w === 400) return (weight === "bold" ? "bold" : "normal");
    return (w === 700 || weight === "bold") ? "bold" : String(w);
};


collection.font = function (sizeOrRole, weight, styleOverride) {
    var base = collection.defaultFontObject();
    var family = (base && base.family) ? base.family : collection.fontFamily();
    var style = styleOverride || (base && base.style) || "normal";
    var weightStr = collection.weightString(weight || (base && base.weight) || "normal");
    var basePx = (base && base.getPixelHeight) ? base.getPixelHeight() : collection.BASE_FONT_SIZE;
    var scale = (basePx > 0 && isFinite(basePx)) ? basePx / collection.BASE_FONT_SIZE : 1;

    var roleMap = {
        title1: 38, title2: 30, title3: 24, title4: 20, title5: 16,
        h1: 38, h2: 30, h3: 24, h4: 20, h5: 16,
        lg: 16, large: 16, default: 14, text: 14, body: 14,
