// Typography code / kbd box: text + 1px border + 0.4em padding each side; height from the
// 1.3 line box plus 0.3em (code: 0.2em + 0.1em) or 0.25em (kbd) padding, 2px (kbd: 3px) border.
// The text bound inside that box, with the same em as codeBox (kbd 90%, code 85% of the text). It
// keeps 1px of the padding: Pencil's RichText renderer measures slightly wider than the canvas.
collection.codeTextBound = function (box, role, font) {
    var pad = 0.4 * font.getPixelHeight() / (role === "kbd" ? 0.9 : 0.85);
    return new Bound(1 + pad - 0.5, 0, Math.max(0, box.w - 2 - 2 * pad + 1), box.h - (role === "kbd" ? 1 : 0));
};
collection.codeBox = function (text, role) {
    var f = collection.font(role, 400), em = f.getPixelHeight() / (role === "kbd" ? 0.9 : 0.85);
