    var f = collection.defaultFontObject();
    var px = (f && f.getPixelHeight) ? f.getPixelHeight() : collection.BASE_FONT_SIZE;
    return (px > 0 && isFinite(px)) ? px / collection.BASE_FONT_SIZE : 1;
