collection.scalePx = function(value) {
    return Math.round(value * collection.uiScale() * 10) / 10;
};

collection.px = function(family, key, fallback) {
    var v = collection.sv(family, key, fallback);
    return typeof v === "number" ? collection.scalePx(v) : v;
