        } else if (typeof v === "number" || type === "Num") {
            value = typeof v === "number" ? collection.numberValue(shape, name, v) : v;
        } else if (type === "StrokeStyle") {
            value = typeof v === "string" ? StrokeStyle.fromString(v) : v;
        } else if (type === "Color") {
            value = typeof v === "string" ? collection.tc(v) : v;
        } else if (type === "Enum" || type === "PlainText") {
            value = v;
        } else {
