    if (state === "error") return { strokeColor: "colorError", focusRingColor: "colorTransparent", disabled: false, showHandlers: false };
    if (state === "warning") return { strokeColor: "colorWarning", focusRingColor: "colorTransparent", disabled: false, showHandlers: false };
    if (state === "disabled") return { strokeColor: "colorBorder", focusRingColor: "colorTransparent", disabled: true, showHandlers: false };
