};

// Input / Input.Password / Input.Search geometry, after the antd 5.29.3 affix wrapper.
// Content starts at border + paddingX. Prefix and suffix icons are iconSize, a gap (paddingXXS)
// away from the text; suffix icons sit left to right as suffix, password eye, search. The
// clear icon is 12px (fontSizeIcon), shown only with a value, and keeps gap / 2 x gap margins
// when suffix icons follow it. The Search enterButton is text + 2 x button padding + 2 x
// border wide and overlaps the input's right border. Every caller passes the same properties,
// so each behavior re-evaluates when any of them changes.
collection.inputLayout = function (box, stroke, paddingX, iconSize, gap, prefixIcon, suffixIcon, allowClear, value, disabled, isPassword, searchMode, buttonText, font, size) {
    var bw = stroke.w, s = iconSize.value, g = gap.value;
