        out.prefixX = left;
        left += s + g;
    }
    out.textX = left;
    var icons = [];
    if (collection.hasImage(suffixIcon)) icons.push("suffixX");
    if (isPassword.value) icons.push("passX");
    if (mode === "icon") icons.push("searchIconX");
