// the hint, whose paragraph keeps the 1em bottom margin of antd's reset.
collection.draggerLayout = function (box, stroke, iconSize, title, titleFont, hint, hintFont) {
    var bw = stroke.w, pad = collection.scalePx(16), lh = collection.themeMetrics().lineHeight || 1.5714285714285714;
    var x = bw + pad, w = Math.max(0, box.w - 2 * x);
    var titleLH = titleFont.getPixelHeight() * lh, hintLH = hintFont.getPixelHeight() * lh;
    var titleH = collection.wrappedLineCount(title, titleFont, w) * titleLH;
    var hintH = collection.wrappedLineCount(hint, hintFont, w) * hintLH;
    var contentH = iconSize.value + pad + titleH + collection.scalePx(4) + hintH + hintFont.getPixelHeight();
    var top = x + Math.max(0, (box.h - 2 * x - contentH) / 2);
