        extra = { box: new Dimension(Math.round(collection.scalePx(800)), Math.round(collection.scalePx(64))), paddingX: Math.round(collection.scalePx(50)) };
    } else if (type === "sider") {
        extra = { box: new Dimension(Math.round(collection.scalePx(200)), Math.round(collection.scalePx(600))), paddingX: Math.round(collection.scalePx(16)) };
    } else if (type === "sider_collapsed") {
        extra = { box: new Dimension(Math.round(collection.scalePx(80)), Math.round(collection.scalePx(600))), paddingX: Math.round(collection.scalePx(8)) };
    } else if (type === "content") {
        extra = { box: new Dimension(Math.round(collection.scalePx(600)), Math.round(collection.scalePx(400))), paddingX: Math.round(collection.scalePx(24)),
