    } else if (type === "footer") {
        extra = { box: new Dimension(Math.round(collection.scalePx(800)), Math.round(collection.scalePx(64))), paddingX: Math.round(collection.scalePx(50)),
                  fillColor: collection.tc("colorBgLayout"), textColor: collection.tc("colorText"), titleColor: collection.tc("colorText"),
                  textAlign: "center", titleFont: collection.font("text", 400) };
