    if (p.titleColor) shape.setProperty("titleColor", p.titleColor);
    if (p.strokeColor) shape.setProperty("strokeColor", p.strokeColor);
    if (p.borderPlacement) shape.setProperty("borderPlacement", p.borderPlacement);
    if (p.paddingX !== undefined) shape.setProperty("paddingX", new Num(p.paddingX));
    if (p.textAlign) shape.setProperty("textAlign", p.textAlign);
    if (p.hasTitle !== undefined) shape.setProperty("hasTitle", new Bool(p.hasTitle));
    if (p.triggerFillColor) shape.setProperty("triggerFillColor", p.triggerFillColor);
    if (p.triggerColor) shape.setProperty("triggerColor", p.triggerColor);
