    // (controlItemBgActive) + colorPrimary; hover itemHoverBg (colorBgTextHover), text unchanged.
    var height = (mode === "horizontal") ? Math.round(collection.scalePx(46)) : Math.round(collection.scalePx(40));
    var paddingX = (mode === "horizontal") ? Math.round(collection.scalePx(16)) : Math.round(collection.scalePx(24));
    var width = (mode === "horizontal")
