    if (p.fillColor) shape.setProperty("fillColor", p.fillColor);
    if (p.textColor) shape.setProperty("textColor", p.textColor);
    if (p.iconColor) shape.setProperty("iconColor", p.iconColor);
    if (p.radius !== undefined) shape.setProperty("radius", new Num(p.radius));
    if (p.paddingX !== undefined) shape.setProperty("paddingX", new Num(p.paddingX));
    shape.setProperty("mode", mode);
    shape.setProperty("state", state);
    if (danger !== undefined) shape.setProperty("danger", new Bool(danger));
